def patternIndex(text: str, pattern: str) -> list[int]:
    
    # initialize list of indices
    indices = []
    for i in range(0, text.__len__()):
        if pattern == text[i:i+pattern.__len__()]:
            indices.append(i)
    return indices

def main():
    list = patternIndex("", "CGTTTCACG")
    for i in list:
        print(i, end = " ")

if __name__ == "__main__":
    main()